use rubato::{Resampler,SincFixedIn,SincInterpolationParameters,SincInterpolationType,WindowFunction};
fn main(){let mut r=SincFixedIn::<f32>::new(48000./44100.,1.,SincInterpolationParameters{sinc_len:128,f_cutoff:0.95,oversampling_factor:128,interpolation:SincInterpolationType::Cubic,window:WindowFunction::BlackmanHarris2},1024,1).unwrap();let mut x=vec![vec![0.;1024]];x[0][200]=1.;let out=r.process(&x,None).unwrap();let peak=out[0].iter().enumerate().max_by(|a,b|a.1.abs().total_cmp(&b.1.abs())).unwrap();println!("delay={} peak={} expected={} after_trim={}",r.output_delay(),peak.0,200.*48000./44100.,peak.0 as isize-r.output_delay()as isize);}
